// Prüfskript Demo-Vorbereitung (ohne laufenden Server, eigenes leeres Datenverzeichnis)
//   node vb-pruefen.mjs hook      → erster Seed löst demoVorbereiten aus (Konten vor jeder Anmeldung da)
//   node vb-pruefen.mjs anmelden  → Hook aus, Anmeldung mit unbekannter @example.com-Adresse löst es aus
import { registerHooks } from "node:module";
import { cpSync, mkdirSync, readFileSync, existsSync } from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

const WURZEL = "C:/Users/SALEADMIN/Downloads/Oekoinvest-Web";
const MODUS = process.argv[2] || "hook";
const LAUF = path.join(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1")), `vb-lauf-${MODUS}-${Date.now().toString(36)}`);

mkdirSync(LAUF, { recursive: true });
cpSync(path.join(WURZEL, "src/data/geo"), path.join(LAUF, "src/data/geo"), { recursive: true });
cpSync(path.join(WURZEL, "public/geo"), path.join(LAUF, "public/geo"), { recursive: true });
process.chdir(LAUF);
if (existsSync(path.join(LAUF, ".data"))) throw new Error("Datenverzeichnis nicht leer");

registerHooks({
  resolve(s, kontext, weiter) {
    if (s.startsWith("@/")) s = pathToFileURL(path.join(WURZEL, "src", s.slice(2))).href;
    if ((s.startsWith(".") || s.startsWith("file:")) && !/\.(m?js|json)$/.test(s)) {
      for (const endung of [".js", "/index.js"]) {
        try {
          return weiter(s + endung, kontext);
        } catch {
          /* nächste */
        }
      }
    }
    return weiter(s, kontext);
  },
});

const B = path.join(WURZEL, "src/lib/plattform/backend");
const demo = await import(pathToFileURL(path.join(B, "demo.js")).href);
const speicher = await import(pathToFileURL(path.join(B, "demo/speicher.js")).href);
const { DEMO_KONTEN } = await import(pathToFileURL(path.join(B, "demo/seed.js")).href);
const { demoVorbereiten } = await import(pathToFileURL(path.join(B, "demo/vorbereiten.js")).href);
console.log("Datenordner:", speicher.DATEN_ORDNER);

const page = readFileSync(path.join(WURZEL, "src/app/login/page.js"), "utf8");
const block = page.slice(page.indexOf("const WEITERE_DEMO_KONTEN"), page.indexOf("];", page.indexOf("const WEITERE_DEMO_KONTEN")));
const weitere = [...block.matchAll(/email:\s*"([^"]+)"/g)].map((m) => m[1]);
const alle = [...new Set([...DEMO_KONTEN.map((k) => k.email), ...weitere])];
console.log(`Konten: ${alle.length} (${DEMO_KONTEN.length} Basis + ${weitere.length} weitere)`);

let fehler = 0;
const t0 = Date.now();
if (MODUS === "anmelden") speicher.nachSeedSetzen(null);
const db0 = await speicher.lesen(); // erster Seed (+ Hook)
console.log(`Erster Zugriff: ${((Date.now() - t0) / 1000).toFixed(1)} s, ${db0.nutzer.length} Konten in der DB`);
if (MODUS === "hook") {
  const fehlen = alle.filter((e) => !db0.nutzer.some((u) => u.email === e));
  console.log(fehlen.length ? `FEHLER: nach erstem Seed fehlen ${fehlen.join(", ")}` : "OK: nach erstem Seed sind alle Konten vorhanden (vor jeder Anmeldung)");
  if (fehlen.length) fehler++;
} else {
  const fehlen = alle.filter((e) => !db0.nutzer.some((u) => u.email === e));
  console.log(`Ohne Hook fehlen nach erstem Seed ${fehlen.length} Konten (erwartet > 0)`);
}

// Reihenfolge im anmelden-Modus: zuerst ein Fachmodul-Konto, damit der Fallback greift
const reihe = MODUS === "anmelden" ? ["bo-akquise@example.com", ...alle.filter((e) => e !== "bo-akquise@example.com")] : alle;
for (const email of reihe) {
  let erg = null;
  let meldung = "";
  try {
    erg = await demo.anmelden({ email, passwort: "Demo-2026!", ip: "127.0.0.1", userAgent: "vb-pruefen" });
  } catch (e) {
    meldung = e?.message || String(e);
  }
  const ok = !!erg && erg.email === email;
  if (!ok) fehler++;
  console.log(`  ${ok ? "ok  " : "FEHL"} ${email}${ok ? "" : ` ${meldung || "(401)"}`}`);
}

// Idempotenz: zweiter Lauf legt nichts doppelt an
const zaehlen = (db) => {
  const z = {};
  for (const [k, w] of Object.entries(db)) {
    if (Array.isArray(w)) z[k] = w.length;
    else if (w && typeof w === "object") for (const [k2, w2] of Object.entries(w)) if (Array.isArray(w2)) z[`${k}.${k2}`] = w2.length;
  }
  return z;
};
const vorher = await speicher.lesen();
const zv = zaehlen(vorher);
const r = await demoVorbereiten();
const nachher = await speicher.lesen();
const zn = zaehlen(nachher);
const diff = Object.keys({ ...zv, ...zn }).filter((k) => zv[k] !== zn[k] && !["aktivitaeten", "anmeldungen", "postausgang", "benachrichtigungen"].includes(k));
const mails = nachher.nutzer.map((u) => u.email);
const doppelt = mails.filter((m, i) => mails.indexOf(m) !== i);
console.log(`Zweiter Lauf demoVorbereiten: ok=${r.ok.length} fehler=${JSON.stringify(r.fehler)}`);
console.log(`Konten vorher/nachher: ${vorher.nutzer.length}/${nachher.nutzer.length}, doppelte E-Mails: ${doppelt.length ? doppelt.join(", ") : "keine"}`);
console.log(`Geänderte Sammlungsgrößen: ${diff.length ? diff.map((k) => `${k} ${zv[k]}→${zn[k]}`).join(", ") : "keine"}`);
if (r.fehler.length || doppelt.length || vorher.nutzer.length !== nachher.nutzer.length || diff.length) fehler++;
console.log(fehler ? `\nERGEBNIS: ${fehler} Fehler` : "\nERGEBNIS: alles grün");
process.exit(fehler ? 1 : 0);

